package Controllers; import Services.CartService; import java.io.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/UpdateCartServlet") public class UpdateCartServlet extends HttpServlet{private final CartService s=new CartService();protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{s.update(r.getSession(),Integer.parseInt(r.getParameter("productId")),Integer.parseInt(r.getParameter("quantity")));p.sendRedirect("ViewCartServlet");}}
